/* Helper: return cached FileContent for filename or load/parse and cache it */
static FileContent* get_or_load_file_content(const char *filename) {
    char filepath[MAX_PATH];
    snprintf(filepath, sizeof(filepath), "%s/%s", ss.storage_path, filename);

    pthread_mutex_lock(&ss.content_mutex);
    for (int i = 0; i < ss.file_content_count; ++i) {
        if (strcmp(ss.file_contents[i].filename, filename) == 0) {
            FileContent *fc = ss.file_contents[i].content;
            pthread_mutex_unlock(&ss.content_mutex);
            return fc;
        }
    }

    if (ss.file_content_count >= MAX_FILES) {
        pthread_mutex_unlock(&ss.content_mutex);
        return NULL; // cache full
    }

    FileContent *fc = init_file_content();
    if (parse_file(filepath, fc) != 0) {
        // treat as empty
        fc->sentence_count = 1;
        fc->sentences[0].capacity = SENTENCE_CAPACITY;
        fc->sentences[0].word_count = 0;
        fc->sentences[0].words = malloc(sizeof(char*) * fc->sentences[0].capacity);
    }

    strncpy(ss.file_contents[ss.file_content_count].filename, filename, MAX_FILENAME - 1);
    ss.file_contents[ss.file_content_count].filename[MAX_FILENAME - 1] = '\0';
    ss.file_contents[ss.file_content_count].content = fc;
    ss.file_content_count++;
    pthread_mutex_unlock(&ss.content_mutex);
    return fc;
}

/* Helper: remove and free cached FileContent when file deleted */
static void remove_cached_file_content(const char *filename) {
    pthread_mutex_lock(&ss.content_mutex);
