        if (strcmp(ss.file_contents[i].filename, filename) == 0) {
            free_file_content(ss.file_contents[i].content);
            // compact array
            for (int j = i; j < ss.file_content_count - 1; ++j) {
                ss.file_contents[j] = ss.file_contents[j + 1];
