// ...existing code...
int write_file_ss(const char *filename, int sent_idx, int word_idx, const char *content) {
    char filepath[MAX_PATH];
    snprintf(filepath, sizeof(filepath), "%s/%s", ss.storage_path, filename);

    log_formatted(LOG_DEBUG, "Write request: file=%s, sent=%d, word=%d, content='%s'",
                  filename, sent_idx, word_idx, content);

    /* create undo backup first (best-effort) */
    if (create_undo_backup(filepath) != 0) {
        log_formatted(LOG_WARNING, "Could not create undo backup (file might be empty)");
    }

    /* Open file just to acquire an advisory lock. */
    int fd = open(filepath, O_RDWR);
    if (fd < 0) {
        log_formatted(LOG_ERROR, "Could not open file %s for writing", filepath);
        return ERR_FILE_NOT_FOUND;
    }

    /* Acquire blocking exclusive lock (advisory) */
    struct flock fl;
    memset(&fl, 0, sizeof(fl));
    fl.l_type = F_WRLCK;
    fl.l_whence = SEEK_SET;
    fl.l_start = 0;
    fl.l_len = 0; /* lock whole file */

    if (fcntl(fd, F_SETLKW, &fl) < 0) {
        log_formatted(LOG_ERROR, "Failed to acquire lock on %s: %s", filepath, strerror(errno));
        close(fd);
        return ERR_SERVER_ERROR;
    }

    /* Parse file into FileContent (local ephemeral) */
    FileContent *fc = init_file_content();
    if (parse_file(filepath, fc) != 0) {
        /* treat as empty */
        log_formatted(LOG_DEBUG, "Could not parse file %s, treating as empty", filepath);
        fc->sentence_count = 1;
        fc->sentences[0].capacity = SENTENCE_CAPACITY;
        fc->sentences[0].word_count = 0;
        fc->sentences[0].words = malloc(sizeof(char*) * fc->sentences[0].capacity);
    }

    if (fc->sentence_count == 0) {
        fc->sentence_count = 1;
        fc->sentences[0].capacity = SENTENCE_CAPACITY;
        fc->sentences[0].word_count = 0;
        fc->sentences[0].words = malloc(sizeof(char*) * fc->sentences[0].capacity);
    }

    log_formatted(LOG_DEBUG, "File has %d sentences before insertion", fc->sentence_count);

    if (sent_idx < 0 || sent_idx >= fc->sentence_count) {
        log_formatted(LOG_ERROR, "Invalid sentence index: %d (file has %d sentences)",
                      sent_idx, fc->sentence_count);
        free_file_content(fc);
        /* release lock */
        fl.l_type = F_UNLCK;
        fcntl(fd, F_SETLK, &fl);
        close(fd);
        return ERR_INVALID_INDEX;
    }

    int words_in_sentence = fc->sentences[sent_idx].word_count;
    log_formatted(LOG_DEBUG, "Sentence %d has %d words, inserting at position %d",
                  sent_idx, words_in_sentence, word_idx);

    int new_sentences = insert_word_in_sentence(fc, sent_idx, word_idx, content);
    if (new_sentences < 0) {
        log_formatted(LOG_ERROR, "Failed to insert word '%s' at sentence %d, word index %d",
                      content, sent_idx, word_idx);
        free_file_content(fc);
        fl.l_type = F_UNLCK;
        fcntl(fd, F_SETLK, &fl);
        close(fd);
        return ERR_INVALID_INDEX;
    }

    log_formatted(LOG_DEBUG, "Insertion successful, %d new sentences created, file now has %d sentences",
                  new_sentences, fc->sentence_count);

    /* expand locks if needed (use your existing per-file/sentence lock tracking) */
    if (new_sentences > 0) {
        init_file_locks(filename, fc->sentence_count);
    }

    /* Write to a temp file in same directory, then atomically rename */
    char tmp_path[MAX_PATH];
    snprintf(tmp_path, sizeof(tmp_path), "%s/.%s.tmp.XXXXXX", ss.storage_path, filename);
    int tmpfd = mkstemp(tmp_path);
    if (tmpfd < 0) {
        log_formatted(LOG_ERROR, "mkstemp failed for %s: %s", tmp_path, strerror(errno));
        free_file_content(fc);
        fl.l_type = F_UNLCK;
        fcntl(fd, F_SETLK, &fl);
        close(fd);
        return ERR_SERVER_ERROR;
    }
    close(tmpfd); /* write_file_content will open by name */

    if (write_file_content(tmp_path, fc) != 0) {
        log_formatted(LOG_ERROR, "Failed to write file content to temp file %s", tmp_path);
        unlink(tmp_path);
        free_file_content(fc);
        fl.l_type = F_UNLCK;
        fcntl(fd, F_SETLK, &fl);
        close(fd);
        return ERR_SERVER_ERROR;
    }

    /* Ensure data is flushed to disk before rename */
    int tfd = open(tmp_path, O_RDONLY);
    if (tfd >= 0) {
        fsync(tfd);
        close(tfd);
    }

    /* Atomically replace original file */
    if (rename(tmp_path, filepath) != 0) {
        log_formatted(LOG_ERROR, "Failed to rename %s -> %s: %s", tmp_path, filepath, strerror(errno));
        unlink(tmp_path);
        free_file_content(fc);
        fl.l_type = F_UNLCK;
        fcntl(fd, F_SETLK, &fl);
        close(fd);
        return ERR_SERVER_ERROR;
    }

    /* cleanup and release lock */
    free_file_content(fc);
    fl.l_type = F_UNLCK;
    if (fcntl(fd, F_SETLK, &fl) < 0) {
        log_formatted(LOG_WARNING, "Failed to release lock on %s: %s", filepath, strerror(errno));
    }
    close(fd);

    log_formatted(LOG_INFO, "Successfully wrote to file: %s at sentence %d, word %d",
                  filename, sent_idx, word_idx);
    return SUCCESS;
}
