    fc->sentence_count = 1;
    fc->sentences[0].capacity = 10;
    fc->sentences[0].word_count = 0;
    fc->sentences[0].words = malloc(sizeof(char*) * fc->sentences[0].capacity);

    char word[MAX_WORD];
    int word_idx = 0;
    int current_sent = 0;
    int c;

    while ((c = fgetc(file)) != EOF) {
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            if (word_idx > 0) {
                word[word_idx] = '\0';
                Sentence *sent = &fc->sentences[current_sent];
                if (sent->word_count >= sent->capacity) {
                    sent->capacity *= 2;
                    sent->words = realloc(sent->words, sizeof(char*) * sent->capacity);
                }
                sent->words[sent->word_count++] = strdup(word);
                word_idx = 0;
            }
        } else if (is_delimiter(c)) {
            /* finish current word first */
            if (word_idx > 0) {
                word[word_idx] = '\0';
                Sentence *sent = &fc->sentences[current_sent];
                if (sent->word_count >= sent->capacity) {
                    sent->capacity *= 2;
                    sent->words = realloc(sent->words, sizeof(char*) * sent->capacity);
                }
                sent->words[sent->word_count++] = strdup(word);
                word_idx = 0;
            }

            /* add the delimiter token to current sentence */
            word[0] = c;
            word[1] = '\0';
            Sentence *sent = &fc->sentences[current_sent];
            if (sent->word_count >= sent->capacity) {
                sent->capacity *= 2;
                sent->words = realloc(sent->words, sizeof(char*) * sent->capacity);
            }
            sent->words[sent->word_count++] = strdup(word);

            /* start a new sentence */
            current_sent++;
            if (current_sent >= fc->capacity) {
                while (fc->capacity <= current_sent) fc->capacity *= 2;
                fc->sentences = realloc(fc->sentences, sizeof(Sentence) * fc->capacity);
            }
            fc->sentences[current_sent].capacity = 10;
            fc->sentences[current_sent].word_count = 0;
            fc->sentences[current_sent].words = malloc(sizeof(char*) * fc->sentences[current_sent].capacity);
            fc->sentence_count = current_sent + 1;
        } else {
            /* normal character -> accumulate into word buffer */
            if (word_idx < MAX_WORD - 1) {
                word[word_idx++] = c;
            } else {
                /* overflow: flush buffer as a word */
                word[word_idx] = '\0';
                Sentence *sent = &fc->sentences[current_sent];
                if (sent->word_count >= sent->capacity) {
                    sent->capacity *= 2;
                    sent->words = realloc(sent->words, sizeof(char*) * sent->capacity);
                }
                sent->words[sent->word_count++] = strdup(word);
                word_idx = 0;
            }
        }
    }

    /* handle trailing word */
    if (word_idx > 0) {
        word[word_idx] = '\0';
        Sentence *sent = &fc->sentences[current_sent];
        if (sent->word_count >= sent->capacity) {
            sent->capacity *= 2;
            sent->words = realloc(sent->words, sizeof(char*) * sent->capacity);
        }
        sent->words[sent->word_count++] = strdup(word);
    }

    /* If the last sentence is empty and we have more than one sentence, drop it */
    if (fc->sentence_count > 1 && fc->sentences[fc->sentence_count - 1].word_count == 0) {
        free(fc->sentences[fc->sentence_count - 1].words);
        fc->sentence_count--;
    }

    /* If file had no delimiters and no words, ensure sentence_count is zero */
    if (fc->sentence_count == 1 && fc->sentences[0].word_count == 0) {
        free(fc->sentences[0].words);
        fc->sentence_count = 0;
