    if (!filename || !sent_idx_str) {
        printf("Usage: WRITE <filename> <sentence_index>\n");
        return;
    }

    int sent_idx = atoi(sent_idx_str);
    if (sent_idx < 0) {
        printf("Invalid sentence index\n");
        return;
    }

    // Ask NM for SS location (existing protocol: get SS info via NM)
    Message req;
    init_message(&req);
    req.type = MSG_INFO; // adjust if you use a different message type for SS lookup
    strcpy(req.sender, client.username);
    strncpy(req.filename, filename, MAX_FILENAME - 1);

    send_message(client.nm_sock, &req);
    Message resp;
    if (recv_message(client.nm_sock, &resp) < 0) {
        printf("Failed to contact name server\n");
        return;
    }
    if (resp.status != SUCCESS) {
        print_error(resp.status);
        return;
    }

    // resp.data expected to be "ip:port" for the SS
    int ss_sock = connect_to_ss(resp.data);
    if (ss_sock < 0) {
        printf("Error: Could not connect to storage server\n");
        return;
    }

    // Try to lock the sentence first
    init_message(&req);
    req.type = MSG_LOCK_SENTENCE;
    strcpy(req.sender, client.username);
    strncpy(req.filename, filename, MAX_FILENAME - 1);
    req.sentence_index = sent_idx;

    if (send_message(ss_sock, &req) < 0) {
        printf("Failed to send lock request\n");
        close(ss_sock);
        return;
    }

    if (recv_message(ss_sock, &resp) < 0) {
        printf("No response from storage server\n");
        close(ss_sock);
        return;
    }

    if (resp.status == ERR_SENTENCE_LOCKED) {
        // Sentence locked by someone else — notify and return to command loop.
        printf("Error: Sentence is locked by another user\n");
        // Do not exit the client program; return so user can try again later.
        close(ss_sock); // close transport socket (optional)
        return;
    } else if (resp.status != SUCCESS) {
        print_error(resp.status);
        close(ss_sock);
        return;
    }

