        req.type = MSG_UNLOCK_SENTENCE;
        strcpy(req.sender, client.username);
        strncpy(req.filename, filename, MAX_FILENAME - 1);
        req.sentence_index = sent_idx;
        send_message(ss_sock, &req);
        close(ss_sock);
        return;
    }
    trim_whitespace(content);

    init_message(&req);
    req.type = MSG_WRITE;
    strcpy(req.sender, client.username);
    strncpy(req.filename, filename, MAX_FILENAME - 1);
    req.sentence_index = sent_idx;
    req.word_index = 1; // or obtain from user as needed
    strncpy(req.data, content, MAX_BUFFER - 1);

    send_message(ss_sock, &req);
    if (recv_message(ss_sock, &resp) < 0) {
        printf("Write failed (no response)\n");
        // attempt to unlock
        init_message(&req);
        req.type = MSG_UNLOCK_SENTENCE;
        strcpy(req.sender, client.username);
        strncpy(req.filename, filename, MAX_FILENAME - 1);
        req.sentence_index = sent_idx;
        send_message(ss_sock, &req);
        close(ss_sock);
        return;
    }

    if (resp.status == SUCCESS) {
        printf("Write successful\n");
    } else {
        print_error(resp.status);
    }

    // Unlock when done
    init_message(&req);
    req.type = MSG_UNLOCK_SENTENCE;
    strcpy(req.sender, client.username);
    strncpy(req.filename, filename, MAX_FILENAME - 1);
    req.sentence_index = sent_idx;
